-- Starter policies for every configured public tab. The school can edit,
-- replace or archive them from Admin -> Policies. Title checks prevent
-- duplicate rows if equivalent content was already added manually.

INSERT INTO `Policy` (`title`, `category`, `effectiveDate`, `status`, `content`, `createdAt`, `updatedAt`)
SELECT 'Student Code of Conduct', 'Student Policies', '2026-11-24 00:00:00.000', 'ACTIVE', '<h2>Purpose</h2><p>This policy sets clear expectations so every student can learn in a safe, respectful and disciplined environment.</p><h2>Expected conduct</h2><ul><li>Attend school regularly and arrive on time in the prescribed uniform.</li><li>Treat students, staff and visitors with courtesy and respect.</li><li>Complete classwork and homework honestly and on time.</li><li>Follow classroom, laboratory, library, playground and transport safety instructions.</li><li>Take care of school property and the belongings of others.</li></ul><h2>Unacceptable conduct</h2><p>Bullying, harassment, fighting, abusive language, cheating, deliberate damage and possession of unsafe or prohibited items are not permitted.</p><h2>Support and consequences</h2><p>Concerns are handled fairly according to their seriousness. The school may use counselling, a parent meeting, a written warning or another proportionate action. Students will be given an opportunity to explain what happened.</p>', NOW(3), NOW(3)
WHERE NOT EXISTS (SELECT 1 FROM `Policy` WHERE `title` = 'Student Code of Conduct');

INSERT INTO `Policy` (`title`, `category`, `effectiveDate`, `status`, `content`, `createdAt`, `updatedAt`)
SELECT 'Teacher and Faculty Professional Conduct', 'Teacher / Faculty Policies', '2026-11-24 00:00:00.000', 'ACTIVE', '<h2>Professional standards</h2><p>All teachers and staff are expected to act professionally, prepare lessons responsibly and support the academic and personal development of every student.</p><h2>Core responsibilities</h2><ul><li>Report on time and follow the approved timetable and curriculum.</li><li>Maintain accurate attendance, assessment and student records.</li><li>Use respectful, age-appropriate and inclusive language.</li><li>Keep student and family information confidential unless disclosure is required for safety or by law.</li><li>Communicate with parents through approved school channels.</li></ul><h2>Student safety</h2><p>Corporal punishment, humiliation, harassment and discrimination are prohibited. Any safeguarding concern must be reported promptly to the Principal or designated school authority.</p><h2>Conflicts and school property</h2><p>Staff must disclose conflicts of interest, use school resources responsibly and obtain approval before publishing student information or photographs.</p>', NOW(3), NOW(3)
WHERE NOT EXISTS (SELECT 1 FROM `Policy` WHERE `title` = 'Teacher and Faculty Professional Conduct');

INSERT INTO `Policy` (`title`, `category`, `effectiveDate`, `status`, `content`, `createdAt`, `updatedAt`)
SELECT 'School Rules and Regulations', 'School Rules & Regulations', '2026-11-24 00:00:00.000', 'ACTIVE', '<h2>General rules</h2><ul><li>Students must carry their school identity card and follow the prescribed uniform and grooming requirements.</li><li>Visitors must report to the school office before entering teaching areas.</li><li>Mobile phones and other personal electronic devices may be brought only with prior permission.</li><li>Unsafe objects, tobacco, alcohol and other prohibited substances are not allowed on campus.</li><li>School property must not be damaged, removed or used without permission.</li></ul><h2>Arrival and departure</h2><p>Students should arrive before assembly and leave only through the approved transport or guardian arrangement. Early departure requires permission from the school office.</p><h2>Health and safety</h2><p>Illness, injury, hazards and emergencies must be reported immediately to a staff member. Students and visitors must follow all safety and evacuation instructions.</p><h2>Communication</h2><p>Official notices are issued by the school office. Parents should keep their contact details current and contact the office when clarification is needed.</p>', NOW(3), NOW(3)
WHERE NOT EXISTS (SELECT 1 FROM `Policy` WHERE `title` = 'School Rules and Regulations');

INSERT INTO `Policy` (`title`, `category`, `effectiveDate`, `status`, `content`, `createdAt`, `updatedAt`)
SELECT 'Attendance and Leave Policy', 'Attendance / Leave Rules', '2026-11-24 00:00:00.000', 'ACTIVE', '<h2>Regular attendance</h2><p>Students are expected to attend every working day and arrive before the morning assembly. Attendance requirements for examinations and promotion follow applicable HPBOSE and school rules.</p><h2>Reporting an absence</h2><p>A parent or guardian should inform the school office as early as possible when a student is absent. A written leave request should state the reason and expected dates.</p><h2>Medical and extended leave</h2><p>The school may request a medical certificate for illness-related or extended absence. Planned leave should be approved in advance wherever possible.</p><h2>Late arrival and early departure</h2><p>Late students must report as directed by the school. A student may leave early only with office approval and an authorised parent, guardian or transport arrangement.</p><h2>Repeated absence</h2><p>The school will contact the family when attendance becomes a concern and may arrange a meeting to agree on appropriate support and next steps.</p>', NOW(3), NOW(3)
WHERE NOT EXISTS (SELECT 1 FROM `Policy` WHERE `title` = 'Attendance and Leave Policy');

INSERT INTO `Policy` (`title`, `category`, `effectiveDate`, `status`, `content`, `createdAt`, `updatedAt`)
SELECT 'Academic and Examination Policy', 'Academic / Examination Rules', '2026-11-24 00:00:00.000', 'ACTIVE', '<h2>Teaching and assessment</h2><p>Teaching follows the applicable HPBOSE curriculum. Student progress may be assessed through classwork, homework, projects, practical work, periodic tests and examinations.</p><h2>Examination conduct</h2><ul><li>Students must arrive on time with the required stationery and admit card where applicable.</li><li>Only permitted materials may be taken into the examination room.</li><li>Students must follow the instructions of the invigilator.</li><li>Copying, unauthorised assistance and use of prohibited material are treated as unfair means.</li></ul><h2>Absence from an assessment</h2><p>A parent or guardian should notify the school promptly. Any alternative assessment is subject to the reason for absence, supporting documents and school or board rules.</p><h2>Results and review</h2><p>Results are shared through approved school channels. Questions about marks should be raised with the subject teacher or school office within the announced review period.</p><h2>Promotion and board rules</h2><p>Promotion, eligibility and certification decisions follow current school and HPBOSE requirements. Where an official board rule differs from this summary, the board rule applies.</p>', NOW(3), NOW(3)
WHERE NOT EXISTS (SELECT 1 FROM `Policy` WHERE `title` = 'Academic and Examination Policy');
